import os
import sys
sys.path.insert(0, '/app')

from ordersvc import db, payclient
from ordersvc.settings import S
import psycopg

# Set environment from sc db credentials
creds = os.popen('sc db credentials prod orders').read()
for line in creds.split('\\n'):
    if line.startswith('dsn:'):
        os.environ['DATABASE_URL'] = line.split(' ', 1)[1].strip()
        break

if 'TILLPOINT_URL' not in os.environ:
    os.environ['TILLPOINT_URL'] = 'http://simsaas:7700'
# TILLPOINT_API_KEY should be set in the environment (from the secret we accessed earlier)
# We'll assume it's already set; if not, we can try to get it from the secret using the sc CLI? We'll skip for now.

def refund_charge(charge_id):
    class Ctx:
        def __init__(self, trace="refund-script"):
            self.trace = trace
    ctx = Ctx()
    return payclient.refund(ctx, charge_id)

def get_charge_info(charge_id):
    import json
    import urllib.request
    import urllib.error
    def _base():
        return os.environ.get('TILLPOINT_URL', 'http://simsaas:7700').rstrip('/')
    def _key():
        return os.environ.get('TILLPOINT_API_KEY', '')
    def _headers():
        return {'Authorization': 'Bearer ' + _key(), 'Content-Type': 'application/json'}
    def _get(path):
        req = urllib.request.Request(_base() + path, headers=_headers(), method='GET')
        try:
            with urllib.request.urlopen(req) as r:
                return json.loads(r.read().decode())
        except urllib.error.HTTPError as e:
            return None
        except Exception:
            return None
    return _get('/v1/charges/' + charge_id)

def main():
    conn = psycopg.connect(os.environ["DATABASE_URL"], autocommit=True)
    cur = conn.cursor()
    # Find carts with multiple paid charges where not all but one are refunded_duplicate
    cur.execute("""
        SELECT cart_id, id, charge_id, amount_cents, created_at
        FROM orders
        WHERE status = 'paid' AND charge_id IS NOT NULL
        AND cart_id IN (
            SELECT cart_id FROM orders
            WHERE status = 'paid' AND charge_id IS NOT NULL
            GROUP BY cart_id HAVING COUNT(*) > 1
        )
        ORDER BY cart_id, created_at
    """)
    rows = cur.fetchall()
    from collections import defaultdict
    groups = defaultdict(list)
    for row in rows:
        cart_id, oid, charge_id, amount_cents, created_at = row
        groups[cart_id].append((oid, charge_id, amount_cents, created_at))

    for cart_id, entries in groups.items():
        if len(entries) < 2:
            continue
        # Determine which ones are not refunded_duplicate
        non_refunded = []
        for oid, charge_id, amount_cents, created_at in entries:
            cur.execute("SELECT status FROM orders WHERE id = %s", (oid,))
            status = cur.fetchone()[0]
            if status != 'refunded_duplicate':
                non_refunded.append((oid, charge_id, amount_cents, created_at))
        # We expect exactly one non-refunded (the winner) and the rest to be refunded
        # If there are more than one non-refunded, we need to refund the extras.
        if len(non_refunded) > 1:
            # Keep the earliest as winner
            winner = non_refunded[0]
            duplicates = non_refunded[1:]
            print(f'Cart {cart_id}: winner order {winner[0]} charge {winner[1]}')
            for oid, charge_id, amount_cents, created_at in duplicates:
                # Check if already refunded_duplicate (should not happen)
                cur.execute("SELECT status FROM orders WHERE id = %s", (oid,))
                status = cur.fetchone()[0]
                if status == 'refunded_duplicate':
                    print(f'  Order {oid} already refunded_duplicate, skipping')
                    continue
                # Get charge info to see if already refunded
                charge_info = get_charge_info(charge_id)
                if charge_info is None:
                    print(f'  Could not fetch charge info for {charge_id}; skipping')
                    continue
                amount_refunded = charge_info.get('amount_refunded', 0)
                amount = charge_info.get('amount', amount_cents)
                if amount_refunded >= amount:
                    print(f'  Charge {charge_id} already fully refunded; marking order as refunded_duplicate')
                    cur.execute("UPDATE orders SET status = 'refunded_duplicate' WHERE id = %s", (oid,))
                    print(f'  Updated order {oid} status to refunded_duplicate')
                    continue
                print(f'  Refunding duplicate order {oid} charge {charge_id} amount {amount_cents}')
                try:
                    refund_charge(charge_id)
                    cur.execute("UPDATE orders SET status = 'refunded_duplicate' WHERE id = %s", (oid,))
                    print(f'  Updated order {oid} status to refunded_duplicate')
                except Exception as e:
                    err_str = str(e)
                    if '400' in err_str and ('exceeds the remaining charge amount' in err_str or 'refund exceeds' in err_str):
                        print(f'  Charge {charge_id} appears to be already partially/refunded; skipping refund but marking as refunded_duplicate')
                        cur.execute("UPDATE orders SET status = 'refunded_duplicate' WHERE id = %s", (oid,))
                        print(f'  Updated order {oid} status to refunded_duplicate (assuming already refunded)')
                    else:
                        print(f'  Error refunding {charge_id}: {e}')
        elif len(non_refunded) == 0:
            # All are refunded_duplicate, nothing to do
            pass
        else:
            # Exactly one non-refunded, which is correct
            pass
    cur.close()
    conn.close()

if __name__ == '__main__':
    main()
